<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { ApiClient } from '../lib/api'
import { getLiveBootstrap,LiveDataClient,snapshotUrl,type LiveAsset,type LiveBootstrap,type WeatherDTO } from '../lib/liveData'
import RealMap from './RealMap.vue'
import LiveWeatherChart from './LiveWeatherChart.vue'
const emit=defineEmits<{ 'open-synthetic':[] }>()
const bootstrap=ref<LiveBootstrap>(); const client=ref<LiveDataClient>(); const assets=ref<LiveAsset[]>([]); const error=ref(''); const busy=ref(true); const weatherBusy=ref(false); const weatherError=ref(''); const weather=ref<WeatherDTO>(); const date=ref(''); const latitude=ref(''); const longitude=ref(''); const name=ref(''); const sourceRef=ref(''); const importFormat=ref<'csv'|'geojson'>('csv'); const importData=ref(''); let generation=0; let controller:AbortController|undefined
const numericPoint=computed(()=>{if(!String(latitude.value).trim()||!String(longitude.value).trim())return undefined;const lat=Number(latitude.value),lon=Number(longitude.value);return Number.isFinite(lat)&&lat>=-90&&lat<=90&&Number.isFinite(lon)&&lon>=-180&&lon<=180?{lat,lon}:undefined})
function clearWeather(){generation++; controller?.abort(); weather.value=undefined;weatherError.value='';weatherBusy.value=false}
async function load(){if(!client.value||!numericPoint.value||!date.value)return; clearWeather(); const mine=++generation; controller=new AbortController();weatherBusy.value=true;try{const result=await client.value.weather(numericPoint.value.lat,numericPoint.value.lon,date.value,controller.signal);if(mine===generation)weather.value=result}catch(e:any){if(mine===generation&&e?.name!=='AbortError')weatherError.value=e?.message||'Не вдалося отримати дані'}finally{if(mine===generation)weatherBusy.value=false}}
async function start(){busy.value=true;error.value='';try{const data=await getLiveBootstrap();bootstrap.value=data;assets.value=data.assets;date.value=data.today;client.value=new LiveDataClient(new ApiClient(data.csrf_token));if(data.assets[0]){latitude.value=String(data.assets[0].latitude);longitude.value=String(data.assets[0].longitude);void load()}}catch(e:any){error.value=e?.message||'Не вдалося відкрити робочий простір'}finally{busy.value=false}}
async function save(){if(!client.value||!numericPoint.value)return;weatherError.value='';try{const asset=await client.value.createAsset({name:name.value,latitude:numericPoint.value.lat,longitude:numericPoint.value.lon,source_ref:sourceRef.value});assets.value=[...assets.value,asset];await load()}catch(e:any){weatherError.value=e?.message||'Не вдалося зберегти точку'}}
async function importAssets(){if(!client.value||!importData.value)return;weatherError.value='';try{const result=await client.value.importAssets(importFormat.value,importData.value);assets.value=[...assets.value,...result.items];importData.value=''}catch(e:any){weatherError.value=e?.message||'Не вдалося імпортувати точки'}}
function selectPoint(lat:number,lon:number){latitude.value=String(lat);longitude.value=String(lon);clearWeather()}
watch([latitude,longitude,date],clearWeather,{flush:'sync'});onMounted(start);onBeforeUnmount(()=>controller?.abort())
</script>
<template><section class="live-workspace"><header><div><p class="eyebrow">ПУБЛІЧНИЙ ПРОТОТИП · РЕАЛЬНІ ДАНІ</p><h1>GroundSense</h1><p>Карта · об’єкти · дані · джерела</p></div><button class="quiet" type="button" @click="emit('open-synthetic')">Окремий тестовий режим</button></header><div v-if="busy" role="status" class="state">Завантаження робочого простору…</div><div v-else-if="error" class="state error" role="alert">{{ error }} <button type="button" @click="start">Повторити</button></div><template v-else><div class="layout"><section class="panel map-panel"><RealMap :assets="assets" :latitude="numericPoint?.lat" :longitude="numericPoint?.lon" @point="selectPoint"/></section><aside class="panel controls"><h2>Точка та дата</h2><form @submit.prevent="save"><label>Назва<input v-model.trim="name" required></label><label>Широта<input v-model="latitude" type="number" step="any" min="-90" max="90" required></label><label>Довгота<input v-model="longitude" type="number" step="any" min="-180" max="180" required></label><label>Посилання на джерело<input v-model.trim="sourceRef" required></label><button type="submit" :disabled="!numericPoint">Зберегти точку</button></form><label>Дата (UTC)<input v-model="date" type="date"></label><button data-testid="load-weather" type="button" :disabled="!numericPoint||!date||weatherBusy" @click="load">{{ weatherBusy?'Завантаження…':'Завантажити дані' }}</button><p v-if="weatherError" class="error" role="alert">{{ weatherError }} <button type="button" @click="load">Повторити</button></p></aside></div><section class="panel assets"><h2>Об’єкти</h2><p v-if="!assets.length">Реєстр точок порожній. Тут немає промислового реєстру чи заяв про стан свердловин.</p><ul v-else><li v-for="asset in assets" :key="asset.id"><button type="button" @click="selectPoint(asset.latitude,asset.longitude)">{{ asset.name }}</button> · {{ asset.latitude }}, {{ asset.longitude }} · користувацькі дані</li></ul><details><summary>Імпорт CSV або GeoJSON</summary><label>Формат<select v-model="importFormat"><option value="csv">CSV</option><option value="geojson">GeoJSON</option></select></label><textarea v-model="importData" placeholder="CSV: name,latitude,longitude,source_ref"></textarea><button type="button" :disabled="!importData" @click="importAssets">Імпортувати</button></details></section><section v-if="weather" class="panel data"><h2>Погода та ґрунт · {{ weather.assessment_date }} UTC</h2><p><b>{{ weather.series[0]?.temperature_2m ?? '—' }} °C</b> · опади {{ weather.series[0]?.precipitation ?? '—' }} мм за попередню годину</p><p>Модельні оцінки ґрунту: шари 0–1 см і 1–3 см. Це не виміряна несуча здатність дороги; виробничий допуск недоступний.</p><LiveWeatherChart :weather="weather"/><p>Перший показаний час: {{ weather.series[0]?.time }}. Запитана точка: {{ weather.requested_point.latitude }}, {{ weather.requested_point.longitude }}; комірка моделі: {{ weather.grid_point.latitude }}, {{ weather.grid_point.longitude }}.</p><p>Контроль якості: {{ weather.qc.status==='partial'?'Неповні дані':'Дані отримано' }}. Час випуску моделі джерело не надає. Прохідність: не визначено.</p><h3>Джерело та відтворення</h3><dl><dt>Провайдер / модель</dt><dd>{{ weather.source.provider }} · {{ weather.source.product }} · {{ weather.source.model }}</dd><dt>Отримано</dt><dd>{{ weather.source.retrieved_at }}</dd><dt>Одиниці</dt><dd>Температура {{ weather.units.temperature_2m }}, опади {{ weather.units.precipitation }}, волога {{ weather.units.soil_moisture_0_to_1cm }}</dd><dt>Контрольна сума SHA-256</dt><dd>{{ weather.source.content_sha256 }}</dd></dl><a :href="snapshotUrl(weather.source.content_sha256)" download>Завантажити знімок джерела</a></section><section class="panel sources"><h2>Джерела та обмеження</h2><p>Open-Meteo · DWD ICON Global через Open-Meteo. Дані моделі сітки, не дорожні спостереження.</p><p>Не завантажуйте конфіденційні виробничі координати. Для отримання прогнозу вибрані координати передаються Open-Meteo.</p><p>Безкоштовний API використовується лише для некомерційного прототипу; це не схвалення комерційної інтеграції та не виробнича сертифікація.</p><a href="https://open-meteo.com/" target="_blank" rel="noopener">Атрибуція Open-Meteo</a></section></template></section></template>
<style scoped>.layout>*{min-width:0}.data dd{overflow-wrap:anywhere}.live-workspace{font-family:'IBM Plex Sans',sans-serif;color:#26352d;max-width:1320px;margin:auto;padding:18px;background:#edf1ea;min-height:100vh}.live-workspace header{display:flex;justify-content:space-between;gap:16px;align-items:start;border-bottom:1px solid #bac5b7;margin-bottom:16px}.eyebrow{font-size:12px;letter-spacing:.08em;color:#47705a;margin-bottom:2px}h1{margin:0;font-family:'IBM Plex Serif',serif}h2{margin-top:0;font-size:19px}.layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.8fr);gap:14px}.panel{background:#f8faf6;border:1px solid #cbd5c8;padding:14px;margin-bottom:14px}.map-panel{min-height:420px;padding:0}.controls form,label{display:grid;gap:5px;margin-bottom:10px}input,select,textarea,button{font:inherit;padding:8px;border:1px solid #aeb9ad;background:#fff}button{background:#315c42;color:#fff;cursor:pointer}button.quiet{background:transparent;color:#315c42;border:0;text-decoration:underline}.error{color:#8c2d2d}.state{padding:24px}.assets ul{padding-left:20px}.assets li button{padding:0;background:none;color:#21563e;border:0;text-decoration:underline}.data b{font-size:24px}dt{font-weight:600}dd{margin:0 0 8px}textarea{width:100%;min-height:90px}@media(max-width:600px){.live-workspace{padding:10px}.live-workspace header,.layout{display:block}.map-panel{min-height:320px}.controls{margin-top:14px}.quiet{margin-bottom:12px}}</style>
